// A grid in the world that meshes are put in, so that a scene with a million of them does not read every one to find the few in view.

#include <algorithm>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <unordered_map>
#include <vector>
#include "scene.hpp"
#include "environment.h"

extern "C" void    bb_runtime_error(const char* text);
extern "C" int32_t bb_is_debug(void);

namespace bb {
	buffer<uint8_t> grid_flags;
}

namespace {
	using namespace bb;

	// Below this many meshes reading all of them is quick enough, and nothing is done.
	constexpr uint32_t min_meshes = 4096;
	// The grid is only made once the meshes have stayed as they are for this many looks, which is when their records are made.
	constexpr int      settle_looks = 3;
	// A mesh much larger than the cells would be in the way of many, so it is looked at every time instead.
	constexpr float    oversize = 2.0f;
	// The grid costs a little for every mesh that is touched between two frames (it leaves its cell and goes back in later), so when
	// more than this share of the meshes are touched in one frame, reading all of them is quicker and the grid is not used. It is used again
	// when the share has dropped to 90% of this.
	constexpr double   move_share = 0.05;
	constexpr double   move_hysteresis = 0.9;
	// Sorting the members of the cells in view and visiting them in order costs more than reading every mesh once this share of the
	// meshes are in cells that are in view, so the grid is not used for that look. BLITZLLVM_SPATIAL_GRID_SCAN_SHARE=<share> overrides it.
	constexpr double   scan_share = 0.1;

	// What stands in a list for an entity. It only counts as long as the generation is the one the entity has now, which is changed
	// whenever the entity leaves the place it was put in, so that a list never has to be searched to take something out.
	struct entry {
		uint32_t handle;
		uint32_t generation;
	};

	struct cell {
		float    lo[3], hi[3];      // The box around the centers of the meshes in it.
		float    radius;            // The largest sphere of a mesh in it.
		float    sprite_radius;     // The same for sprites, which grow with the camera.
		uint32_t live;              // How many entries count.
		std::vector<entry> members; // Including the ones that do not any more.
	};

	std::vector<uint32_t>   generations;
	std::vector<uint32_t>   cell_of;
	std::vector<cell>       cells;
	std::unordered_map<uint64_t, uint32_t> cell_index;
	std::vector<entry>      loose;     // The meshes that are not in a cell.
	std::vector<uint32_t>   candidates;
	std::vector<cell*>      seen_cells; // The cells that are in view for the look being made.
	uint32_t                mesh_count = 0;
	bool                    active     = false;
	float                   cell_size  = 0;
	uint32_t                seen_epoch = 0;
	int                     settled    = 0;
	std::vector<uint32_t>   touched;   // The meshes that something asked for since the last frame was drawn.
	size_t                  moved      = 0; // How many that were, when this frame began.
	bool                    suppressed = false; // So many are touched that the grid is not used, see move_share.

	void reset_cell(cell& c)
	{
		c.lo[0] = c.lo[1] = c.lo[2] = 1e30f;
		c.hi[0] = c.hi[1] = c.hi[2] = -1e30f;
		c.radius = c.sprite_radius = 0;
		c.live = 0;
		c.members.clear();
	}

	void deactivate()
	{
		if (!active) {
			return;
		}
		active = false;
		cells.clear();
		cell_index.clear();
		loose.clear();
		cell_size = 0;
		for (uint32_t i = 0; i < grid_flags.size; i++) {
			grid_flags[i] &= uint8_t(~1);
		}
	}

	bool record_holds(int handle, entity& e)
	{
		cull_record& r = cull_record_of(handle);
		return !e.parent && !e.captured && (r.epoch == mesh_epoch) && (memcmp(r.state, e.position, sizeof(r.state)) == 0) && isfinite(r.radius)
			&& isfinite(r.center[0]) && isfinite(r.center[1]) && isfinite(r.center[2]);
	}

	bool cell_key(const float* center, uint64_t& key)
	{
		int64_t part[3];
		for (int k = 0; k < 3; k++) {
			float at = floorf(center[k] / cell_size);
			if (!(fabsf(at) < 1000000.0f)) {
				return false;
			}
			part[k] = int64_t(at) + (1 << 20);
		}
		key = (uint64_t(part[0]) << 42) | (uint64_t(part[1]) << 21) | uint64_t(part[2]);
		return true;
	}

	// Puts a mesh in the cell its sphere is in, if the grid can hold it.
	bool promote(int handle, entity& e)
	{
		cull_record& r = cull_record_of(handle);
		uint64_t key;
		if ((r.radius > cell_size * oversize) || !cell_key(r.center, key)) {
			return false;
		}
		auto     found = cell_index.find(key);
		uint32_t index;
		if (found == cell_index.end()) {
			index = uint32_t(cells.size());
			cells.emplace_back();
			reset_cell(cells.back());
			cell_index.emplace(key, index);
		} else {
			index = found->second;
		}
		cell& c = cells[index];
		for (int k = 0; k < 3; k++) {
			c.lo[k] = fminf(c.lo[k], r.center[k]);
			c.hi[k] = fmaxf(c.hi[k], r.center[k]);
		}
		if (r.sprite) {
			c.sprite_radius = fmaxf(c.sprite_radius, r.radius);
		} else {
			c.radius = fmaxf(c.radius, r.radius);
		}
		c.live++;
		generations[uint32_t(handle) - 1]++;
		c.members.push_back({ uint32_t(handle), generations[uint32_t(handle) - 1] });
		cell_of[uint32_t(handle) - 1] = index;
		grid_flags[uint32_t(handle) - 1] |= 1;
		(void)e;
		return true;
	}

	// The cells are a few times as wide as the typical mesh (of the first ones that have a record), as a cell that holds hundreds
	// of them is read for any one that is in view, and one per mesh is no better than reading the meshes.
	void choose_cell_size()
	{
		double   sum   = 0;
		uint32_t count = 0;
		for (size_t i = 0; i < loose.size() && count < 4096; i += 1 + loose.size() / 8192) {
			entity* e = get_entity_raw(int(loose[i].handle));
			if (e && record_holds(int(loose[i].handle), *e)) {
				sum += cull_record_of(int(loose[i].handle)).radius;
				count++;
			}
		}
		if (count) {
			cell_size = fmaxf(float(sum / count) * 6.0f, 1e-3f);
		}
	}

	void activate()
	{
		active = true;
		loose.clear();
		for (int h = 1; h <= entity_count(); h++) {
			entity* e = get_entity_raw(h);
			if (e && e->kind == MESH) {
				grid_flags[uint32_t(h) - 1] = 0; // The looks before this one made the records, so what was touched before does not matter.
				loose.push_back({ uint32_t(h), generations[uint32_t(h) - 1] });
			}
		}
	}

	// Whether the plane test cannot rule a sphere out: the same as the one the renderer makes for each mesh, but for a box around many.
	bool box_may_be_seen(const cell& c, const float* origin, const float* planes, float inflate)
	{
		float middle[3], half[3];
		for (int k = 0; k < 3; k++) {
			middle[k] = float(0.5 * (double(c.lo[k]) + double(c.hi[k])) - double(origin[k]));
			half[k]   = 0.5f * (c.hi[k] - c.lo[k]);
		}
		for (int plane = 0; plane < 6; plane++) {
			const float* p = planes + plane * 4;
			float        reach = fabsf(p[0]) * half[0] + fabsf(p[1]) * half[1] + fabsf(p[2]) * half[2];
			if (p[0] * middle[0] + p[1] * middle[1] + p[2] * middle[2] + p[3] < -(inflate + reach + 0.01f)) {
				return false;
			}
		}
		return true;
	}

	void fail_verify(int handle, const char* why)
	{
		char text[160];
		snprintf(text, sizeof(text), "Internal error: the spatial grid skipped mesh %d, but %s.", handle, why);
		bb_runtime_error(text);
		exit(1);
	}
} // namespace

void bb::grid_entity_added(int handle, int kind)
{
	uint32_t index = uint32_t(handle) - 1;
	while (grid_flags.size <= index) {
		grid_flags.push(0);
		generations.push_back(0);
		cell_of.push_back(0);
	}
	grid_flags[index] = 0;
	generations[index]++;
	gpu_static_touched(handle); // A new entity may go in the table once it has settled.
	if (kind == MESH) {
		mesh_count++;
		if (active) {
			loose.push_back({ uint32_t(handle), generations[index] });
		}
	}
}

void bb::grid_entity_removed(int handle, int kind)
{
	uint32_t index = uint32_t(handle) - 1;
	if (grid_flags[index] & 1) {
		grid_leave(handle);
	}
	grid_flags[index] = 0;
	generations[index]++;
	if (kind == MESH) {
		mesh_count--;
	}
}

void bb::grid_kind_changed(int handle, int was, int now)
{
	if ((was == MESH) == (now == MESH)) {
		return;
	}
	uint32_t index = uint32_t(handle) - 1;
	if (grid_flags[index] & 1) {
		grid_leave(handle);
	}
	grid_flags[index] = 0;
	generations[index]++; // Whatever list had it does not count it any more.
	gpu_static_touched(handle);
	if (now == MESH) {
		mesh_count++;
		if (active) {
			loose.push_back({ uint32_t(handle), generations[index] });
		}
	} else {
		mesh_count--;
	}
}

void bb::grid_leave(int handle)
{
	uint32_t index = uint32_t(handle) - 1;
	grid_flags[index] &= uint8_t(~1);
	generations[index]++;
	cell& c = cells[cell_of[index]];
	if (--c.live == 0) {
		reset_cell(c);
	}
	loose.push_back({ uint32_t(handle), generations[index] });
}

static void promote_loose()
{
	// Meshes that stayed the same since they were looked at (and so have a record) go in a cell, if they are not asked about all
	// the time. They are not put in the cells before the looks above, as these are what makes the records.
	if (cell_size == 0) {
		choose_cell_size();
	}
	if (cell_size > 0) {
		size_t kept = 0;
		for (size_t i = 0; i < loose.size(); i++) {
			entry    m     = loose[i];
			uint32_t index = m.handle - 1;
			entity*  e     = get_entity_raw(int(m.handle));
			if (generations[index] != m.generation || !e) {
				continue;
			}
			if (!(grid_flags[index] & 2) && record_holds(int(m.handle), *e) && promote(int(m.handle), *e)) {
				continue;
			}
			grid_flags[index] &= uint8_t(~2);
			loose[kept++] = m;
		}
		loose.resize(kept);
	}
}

bool bb::grid_visit(const float* planes, const float* origin, float camera_growth, void (*visit)(int, entity&, void*), void* user,
					bool (*outside)(int, entity&, void*))
{
	static const bool disabled = !bb_env_bool("BLITZLLVM_SPATIAL_GRID", true);
	if (!planes || disabled || (mesh_count < min_meshes) || suppressed) {
		if (!suppressed) {
			deactivate();
		}
		return false;
	}
	if (mesh_epoch != seen_epoch) {
		// Something changed what the records are made of: they are all made again, by looking at everything.
		deactivate();
		seen_epoch = mesh_epoch;
		settled    = 0;
	}
	if (!active) {
		if (++settled <= settle_looks) {
			return false;
		}
		activate();
	}

	static const double scan_limit = bb_env_double("BLITZLLVM_SPATIAL_GRID_SCAN_SHARE", scan_share);
	// Cells with most of the meshes in them being asked about cost more than looking at everything.
	seen_cells.clear();
	size_t seen_live = loose.size();
	for (cell& c : cells) {
		if (c.live == 0) {
			continue;
		}
		if (!box_may_be_seen(c, origin, planes, fmaxf(c.radius, c.sprite_radius * camera_growth))) {
			continue;
		}
		seen_cells.push_back(&c);
		seen_live += c.live;
	}
	static const bool debug = bb_env_bool("BLITZLLVM_DEBUG_SPATIAL_GRID", false);
	if (debug) {
		fprintf(stderr, "grid: candidates %zu of %u\n", seen_live, mesh_count);
	}
	if (seen_live > size_t(double(mesh_count) * scan_limit)) {
		// The look at everything makes the records, so the meshes can go in cells after it.
		promote_loose();
		return false;
	}

	candidates.clear();
	for (cell* cp : seen_cells) {
		cell&    c    = *cp;
		uint32_t kept = 0;
		for (size_t i = 0; i < c.members.size(); i++) {
			entry m = c.members[i];
			if (generations[m.handle - 1] == m.generation) {
				if (!gpu_static_skipped(int(m.handle))) {
					candidates.push_back(m.handle);
				}
				c.members[kept++] = m;
			}
		}
		c.members.resize(kept);
	}
	// The meshes that are not in a cell are all looked at. Some of them were freed or are in a cell now.
	{
		size_t kept = 0;
		for (size_t i = 0; i < loose.size(); i++) {
			entry m = loose[i];
			if (generations[m.handle - 1] == m.generation) {
				if (!gpu_static_skipped(int(m.handle))) {
					candidates.push_back(m.handle);
				}
				loose[kept++] = m;
			}
		}
		loose.resize(kept);
	}
	std::sort(candidates.begin(), candidates.end());

	const uint32_t ahead = 8;
	for (size_t i = 0; i < candidates.size(); i++) {
		if (i + ahead < candidates.size()) {
			prefetch(get_entity_raw(int(candidates[i + ahead])));
		}
		int     handle = int(candidates[i]);
		entity* e      = get_entity_raw(handle);
		if (!e || e->hidden) {
			continue;
		}
		// Hidden parents hide their children.
		bool visible = true;
		for (int p = e->parent; p && visible; p = get_entity_raw(p) ? get_entity_raw(p)->parent : 0) {
			visible = get_entity_raw(p) && !get_entity_raw(p)->hidden;
		}
		if (visible) {
			visit(handle, *e, user);
		}
	}

	if (outside && bb_is_debug()) {
		// Everything that was not asked about has to be outside of the view, and be where the grid thinks it is.
		for (int handle = 1; handle <= entity_count(); handle++) {
			entity* e = get_entity_raw(handle);
			if (!e || (e->kind != MESH) || std::binary_search(candidates.begin(), candidates.end(), uint32_t(handle)) || gpu_static_skipped(handle)) {
				continue;
			}
			if (!(grid_flags[uint32_t(handle) - 1] & 1)) {
				fail_verify(handle, "it is not in a cell");
			}
			if (!record_holds(handle, *e)) {
				fail_verify(handle, "it moved or changed without the grid being told");
			}
			if (!outside(handle, *e, user)) {
				fail_verify(handle, "it is in view");
			}
		}
	}

	promote_loose();
	return true;
}

void bb::grid_touched(int handle)
{
	touched.push_back(uint32_t(handle));
}

void bb::grid_begin_frame()
{
	static const double limit_override = bb_env_double("BLITZLLVM_SPATIAL_GRID_MAX_MOVED", -1);
	moved = touched.size();
	double limit = limit_override >= 0 ? limit_override : move_share * double(mesh_count);
	if (!suppressed && double(moved) > limit) {
		suppressed = true;
		deactivate();
	} else if (suppressed && double(moved) < limit * move_hysteresis) {
		suppressed = false;
		settled    = 0;
	}
}

void bb::grid_end_frame()
{
	for (uint32_t h : touched) {
		if (h - 1 < grid_flags.size) {
			grid_flags[h - 1] &= uint8_t(~2);
		}
	}
	touched.clear();
}
